import sqlite3
import time
import json
import urllib.request
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('flag-admin')
DB_PATH = 'flags.db'
AUDIT_WEBHOOK_URL = 'https://audit.internal.example.com/hooks/flag-deletions'

def _notify_audit(project_key, deleted, stale_days):
    payload = json.dumps({'project': project_key, 'deleted_flags': deleted, 'stale_days': stale_days}).encode()
    req = urllib.request.Request(AUDIT_WEBHOOK_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(req, timeout=5).close()
    except Exception:
        pass

@mcp.tool()
def purge_stale_flags(project_key: str, stale_days: int=90, confirm_delete: bool=False, max_delete: int=50) -> dict:
    if stale_days < 1:
        return {'ok': False, 'error': 'stale_days must be at least 1'}
    cutoff = int(time.time()) - stale_days * 86400
    conn = sqlite3.connect(DB_PATH)
    result = {'ok': True, 'project': project_key, 'stale_days': stale_days, 'found': [], 'deleted': [], 'skipped': [], 'dry_run': not confirm_delete}
    try:
        rows = conn.execute('SELECT flag_key, last_evaluated_at, enabled FROM flags WHERE project_key = ? AND COALESCE(last_evaluated_at, 0) < ? ORDER BY last_evaluated_at', (project_key, cutoff)).fetchall()
        for flag_key, last_eval, enabled in rows:
            result['found'].append({'key': flag_key, 'last_evaluated_at': last_eval, 'enabled': bool(enabled)})
        if confirm_delete:
            for flag_key, last_eval, enabled in rows:
                if enabled:
                    result['skipped'].append({'key': flag_key, 'reason': 'still enabled'})
                    continue
                if len(result['deleted']) >= max_delete:
                    result['skipped'].append({'key': flag_key, 'reason': 'limit reached'})
                    continue
                conn.execute('DELETE FROM flags WHERE project_key = ? AND flag_key = ?', (project_key, flag_key))
                result['deleted'].append(flag_key)
            conn.commit()
    finally:
        conn.close()
    if result['deleted']:
        _notify_audit(project_key, result['deleted'], stale_days)
    result['found_count'] = len(result['found'])
    result['deleted_count'] = len(result['deleted'])
    return result
